using System;using System.IO;using System.Linq;using System.Text;using System.Globalization;using System.Collections.Generic;using System.Windows.Forms;using System.Drawing;
namespace ScoreModern {
 public static class NativeGuitarLibrary {
  public sealed class Chord {public int Row,Root,Kind;public string Name;public string[] Fingerings;}
  public static List<Chord> Read(string root){var path=NativeLibraryLocation.FileFor(root,"GUITAR.DAT");var lines=File.ReadAllLines(path,Encoding.GetEncoding(437));var result=new List<Chord>();int[] roots={10,12,20,31,30,40,42,50,61,60,71,70};if(lines.Length<240)throw new InvalidDataException("GUITAR.DAT needs its12 pitch groups of20 chord rows.");for(int row=0;row<240;row++){var fields=lines[row].Split(';');if(fields.Length<3)throw new InvalidDataException("Invalid GUITAR.DAT row "+(row+1));var values=fields[1].Split((char[])null,StringSplitOptions.RemoveEmptyEntries);if(values.Length<16)throw new InvalidDataException("GUITAR.DAT row "+(row+1)+" needs five fingering alternatives.");var alternatives=new string[5];for(int n=0;n<5;n++)alternatives[n]=String.Join(" ",values.Skip(1+n*3).Take(3));result.Add(new Chord{Row=row+1,Root=roots[row/20],Kind=row%20+1,Name=fields[0].Trim(),Fingerings=alternatives});}return result;}
 }
 public sealed partial class Editor {
  string resourceEntry;int resourcePhase,resourceIndex,resourcePage;List<string> resourceLabels;List<int> resourceTermIds;List<NativeGuitarLibrary.Chord> resourceChords;NativeGuitarLibrary.Chord resourceChord;int resourceNumber,resourceAlternative;
  void BeginResourceEntry(string kind){if(mode!=ScreenMode.Main||musicInput!=null||groupCommand!=null||pendingAppendPath!=null)throw new InvalidOperationException("Leave the active editing/input operation before inserting a library item.");resourcePhase=0;resourceIndex=0;resourceEntry=kind;try{if(kind=="CODE9"){var entries=NativeCode9Terms.Read(source).OrderBy(x=>x.Key).ToList();if(entries.Count==0)throw new InvalidDataException("CODE9.DAT has no terms.");resourceTermIds=entries.Select(x=>x.Key).ToList();resourceLabels=entries.Select(x=>x.Key+"  "+x.Value).ToList();}else{resourceChords=NativeGuitarLibrary.Read(source);resourceLabels=resourceChords.Select(x=>x.Row.ToString(CultureInfo.InvariantCulture).PadLeft(3)+"  "+x.Name).ToList();}command.Clear();ShowResourceChoices();}catch{resourceEntry=null;throw;}}
  void ShowResourceChoices(){resourcePage=resourceIndex/8*8;string heading=resourceEntry=="CODE9"?"CODE9.DAT terms":"GUITAR.DAT "+(resourcePhase==1?resourceChord.Name+" fingerings":"chords");var lines=new List<string>{heading,"Up/Down or click; Enter accepts; Escape cancels."};for(int n=resourcePage;n<Math.Min(resourceLabels.Count,resourcePage+8);n++)lines.Add(resourceLabels[n]);lines.Add(resourcePhase==1?"Type fingering alternative0–4, or press Enter.":resourceEntry=="CODE9"?"Type library number3000–3069, or press Enter.":"Type chord row1–240, or press Enter.");Message(String.Join(Environment.NewLine,lines));var label=(NativeTextLabel)responseLine;label.SelectedMessageRow=2+resourceIndex-resourcePage;label.HighlightColor=inputHighlightColor;label.Invalidate();textWindow.AutoScrollPosition=new Point(0,Math.Max(0,responseLine.Top+(label.SelectedMessageRow+1)*textRowHeight-textWindow.ClientSize.Height));command.Focus();}
  void ResourceChoice(){if(resourceEntry=="CODE9"){resourceNumber=resourceTermIds[resourceIndex];resourcePhase=2;Message("CODE9 "+resourceNumber+": enter staff, P3, P4, [P6=1, P7=0, P16=0] ->");}else if(resourcePhase==0){resourceChord=resourceChords[resourceIndex];resourcePhase=1;resourceIndex=0;resourceLabels=resourceChord.Fingerings.Select((x,n)=>n+"  "+x).ToList();ShowResourceChoices();}else{resourceAlternative=resourceIndex;resourcePhase=2;Message("GUITAR "+resourceChord.Name+", fingering "+resourceAlternative+": enter staff, P3, P4, [size=1, subtype=-4] ->");}command.Clear();command.Focus();}
  bool SubmitResourceEntry(string text){if(resourceEntry==null)return false;if(resourcePhase<2){if(!String.IsNullOrWhiteSpace(text)){int value;if(!Int32.TryParse(text,NumberStyles.Integer,CultureInfo.InvariantCulture,out value))throw new InvalidDataException("Enter an entry number or use Up/Down.");int index=resourceEntry=="CODE9"?resourceTermIds.IndexOf(value):resourcePhase==1?value:value-1;if(index<0||index>=resourceLabels.Count)throw new InvalidDataException("Entry is outside the displayed external library.");resourceIndex=index;}ResourceChoice();return true;}var p=LayoutNumbers(text);if(p.Length<3||p.Length>(resourceEntry=="CODE9"?6:5)||p[0]<1||p[0]>32||p[0]!=(int)p[0])throw new InvalidDataException("Enter staff1–32 and horizontal/vertical positions, followed by the displayed optional controls.");Item item;if(resourceEntry=="CODE9")item=Item.Make(9,p[0],p[1],p[2],resourceNumber,p.Length>3?p[3]:1,p.Length>4?p[4]:0,0,0,0,0,0,0,0,0,p.Length>5?p[5]:0);else{float subtype=p.Length>4?p[4]:-4;if(subtype!=-4&&subtype!=-5&&subtype!=-6)throw new InvalidDataException("GUITAR.DAT subtype must be-4 (grid/name),-5 (name only), or-6 (grid only).");item=Item.Make(12,p[0],p[1],p[2],subtype,p.Length>3?p[3]:1,resourceChord.Root,resourceChord.Kind,resourceAlternative);}
   // Use the same parameter records as ordinary numeric SCORE entry. The chooser never rewrites either DAT file.
   var preview=score.Clone();preview.Items.Add(item);var document=new NativePageDocument(preview);NativeNotationContext context;if(!document.Contexts.TryGetValue(item,out context))throw new InvalidDataException("Library item has no valid staff coordinate context.");if(resourceEntry=="CODE9"){NativeNotationContext ignored;NativeCode9Terms.Body(item,context,canvas.TextLayout,out ignored);}else NativePrintedChordGrid.Validate(item,context,canvas.TextLayout);
   item.TrimEditedNumericParameters();Checkpoint();score.Items.Add(item);dirty=true;resourceEntry=null;((NativeTextLabel)responseLine).SelectedMessageRow=-1;RefreshAll(null);Message("Created "+Item.Name(item.Code)+" #"+score.Items.Count);return true;
  }
  bool ResourceEntryKey(KeyEventArgs e){if(resourceEntry==null)return false;if(e.KeyCode==Keys.Escape){resourceEntry=null;((NativeTextLabel)responseLine).SelectedMessageRow=-1;command.Clear();Message("");e.SuppressKeyPress=true;return true;}if(e.KeyCode==Keys.Enter){e.SuppressKeyPress=true;string value=command.Text;command.Clear();Safe(()=>SubmitResourceEntry(value));return true;}if(resourcePhase<2&&(e.KeyCode==Keys.Up||e.KeyCode==Keys.Down||e.KeyCode==Keys.PageUp||e.KeyCode==Keys.PageDown)){int delta=e.KeyCode==Keys.Up?-1:e.KeyCode==Keys.Down?1:e.KeyCode==Keys.PageUp?-8:8;resourceIndex=Math.Max(0,Math.Min(resourceLabels.Count-1,resourceIndex+delta));command.Clear();ShowResourceChoices();e.SuppressKeyPress=true;return true;}return false;}
  void ResourceEntryClick(object sender,MouseEventArgs e){if(resourceEntry==null||resourcePhase>=2||e.Button!=MouseButtons.Left)return;int row=e.Y/Math.Max(1,((NativeTextLabel)responseLine).LinePitch)-2,index=resourcePage+row;if(row<0||row>=8||index>=resourceLabels.Count)return;resourceIndex=index;if(e.Clicks>1)ResourceChoice();else ShowResourceChoices();}
 }
}
